using System.Globalization;
using System.Xml.Linq;
using ChartForgeX.Core;
using ChartForgeX.Markup.Mermaid;
using ChartForgeX.Mermaid;
using ChartForgeX.Primitives;
using ChartForgeX.Rendering;
using ChartForgeX.Themes;
using ChartForgeX.Typography;
using ChartForgeX.VisualArtifacts;
using Xunit;
namespace ChartForgeX.Tests;
[Collection(nameof(FontRegistryCollection))]
public sealed class SequenceSourceDefaultsTests {
    [Theory] [InlineData(VisualThemeMode.Light)] [InlineData(VisualThemeMode.Dark)]
    public void NativeNullEmptyAndReferenceContoursStayExactWhileSourceDefaultsAreSeparate(VisualThemeMode mode) {
        var model=Native();model.ThemeMode=mode;model.AddBlock(SequenceArtifactBlockKind.Reference,"Audit",0,0,true);var svg=model.ToSvg();var png=model.ToPng();var json=model.ToVisualArtifact().ToInterchangeJson();SequenceMessageFixture.Capture("sequence-default-reference-null-"+mode,model);model.Layout=new SequenceLayoutPolicy();SequenceMessageFixture.Capture("sequence-default-reference-empty-"+mode,model);Assert.Equal(svg,model.ToSvg());Assert.Equal(png,model.ToPng());Assert.Equal(json,model.ToVisualArtifact().ToInterchangeJson());Assert.Contains("sequence-reference-tab",svg);
    }
    [Theory] [InlineData(SequenceArtifactBlockKind.Loop)] [InlineData(SequenceArtifactBlockKind.Alt)] [InlineData(SequenceArtifactBlockKind.Opt)] [InlineData(SequenceArtifactBlockKind.Par)]
    public void KeywordTabAndCompleteTitleUseOneMeasuredAllocationAndRestoreNativePixels(SequenceArtifactBlockKind kind) {
        var model=Native();model.AddBlock(kind,"Complete review title",0,0);model.Layout=new SequenceLayoutPolicy(fragmentTabMinimumWidth:120,fragmentTabMinimumHeight:60,fragmentLabelPadding:8);var prepared=model.Prepare(SequenceMessageFixture.Context());SequenceMessageFixture.Capture("sequence-default-tab-"+kind,prepared);var tab=prepared.Regions.Single(r=>r.Role=="sequence-fragment-tab");var title=prepared.Regions.Single(r=>r.Role=="sequence-fragment-title");Assert.Equal(120,tab.Bounds.Width);Assert.Equal(60,tab.Bounds.Height);Assert.True(title.Bounds.Left>tab.Bounds.Right);Assert.Equal("Complete review title",title.Label);var xml=XDocument.Parse(prepared.ToSvg());Assert.Contains(xml.Descendants(),e=>e.Name.LocalName=="text"&&e.Value==kind.ToString().ToLowerInvariant());Assert.Contains(xml.Descendants(),e=>e.Name.LocalName=="text"&&e.Value=="Complete review title");var restored=VisualArtifactInterchangeEnvelope.FromJson(prepared.ToArtifact(model.Id,VisualArtifactKind.Sequence).ToInterchangeJson()).ToSequenceArtifact();var again=restored.Prepare(SequenceMessageFixture.Context());Assert.Equal(prepared.ToSvg(),again.ToSvg());Assert.Equal(prepared.ToPng(),again.ToPng());Assert.Equal(120,restored.Layout!.FragmentTabMinimumWidth);Assert.Equal(60,restored.Layout.FragmentTabMinimumHeight);
    }
    [Theory] [InlineData(true)] [InlineData(false)]
    public void FooterMarginChangesOnlyMirroredTrailingSpaceAndKeepsRoutesHeadersAndLifelines(bool mirrored) {
        SequenceArtifact Model(double margin){var m=Native();for(var i=0;i<20;i++)m.AddMessage("A","B","Save "+i);m.Layout=new SequenceLayoutPolicy(mirrorParticipants:mirrored,footerBottomMargin:margin);return m;}
        var a=Model(1);var b=Model(21);var pa=SequencePreparedCompiler.PrepareDefault(a);var pb=SequencePreparedCompiler.PrepareDefault(b);SequenceMessageFixture.Capture("sequence-default-footer-"+mirrored+"-1",pa);SequenceMessageFixture.Capture("sequence-default-footer-"+mirrored+"-21",pb);Assert.Equal(mirrored?20:0,pb.Size.Height-pa.Size.Height,8);var ea=pa.ToArtifact(a.Id,VisualArtifactKind.Sequence).ToInterchangeEnvelope();var eb=pb.ToArtifact(b.Id,VisualArtifactKind.Sequence).ToInterchangeEnvelope();Assert.Equal(ea.Nodes.Select(n=>(n.X,n.Y,n.Width,n.Height)),eb.Nodes.Select(n=>(n.X,n.Y,n.Width,n.Height)));Assert.Equal(ea.Edges.SelectMany(e=>e.ResolvedRoute).Select(p=>(p.X,p.Y)),eb.Edges.SelectMany(e=>e.ResolvedRoute).Select(p=>(p.X,p.Y)));var la=Lines(pa);var lb=Lines(pb);Assert.Equal(la.Select(x=>x.Attribute("y2")!.Value),lb.Select(x=>x.Attribute("y2")!.Value));if(!mirrored){Assert.Equal(pa.ToSvg(),pb.ToSvg());Assert.Equal(pa.ToPng(),pb.ToPng());}
    }
    [Theory] [InlineData(0)] [InlineData(.5)] [InlineData(4)]
    public void CanonicalStrokeControlsPaintExtentDashAlphaAndDetachedPortableFacts(double width) {
        var model=Native();var dash=new[]{3d,2d};model.Paint.Lifeline=ChartColor.FromHex("#123456");model.Paint.LifelineStroke=new ChartStrokeStyle(width:width,opacity:.5,dash:dash);dash[0]=99;var prepared=model.Prepare(SequenceMessageFixture.Context());SequenceMessageFixture.Capture("sequence-default-stroke-"+width.ToString(CultureInfo.InvariantCulture),prepared);var fact=prepared.ToArtifact(model.Id,VisualArtifactKind.Sequence).ToInterchangeEnvelope();var restored=VisualArtifactInterchangeEnvelope.FromJson(fact.ToJson()).ToSequenceArtifact();Assert.Equal(width,restored.Paint.LifelineStroke!.Width);Assert.Equal(new[]{3d,2d},restored.Paint.LifelineStroke.Dash);Assert.Equal(.5,restored.Paint.LifelineStroke.Opacity);Assert.All(prepared.Regions.Where(r=>r.Role=="sequence-lifeline"),r=>Assert.Equal(width,r.Bounds.Width));var again=restored.Prepare(SequenceMessageFixture.Context());Assert.Equal(prepared.ToSvg(),again.ToSvg());Assert.Equal(prepared.ToPng(),again.ToPng());model.Paint.LifelineStroke=null;model.Paint.Lifeline=ChartColor.Black;Assert.Equal(width,fact.Sequence!.LifelineStroke!.Width);
    }
    [Fact] public void SourceOmittedValuesLowerOnceWithoutFakeSettingsAndExplicitHostDimensionsStillWin() {
        var result=MermaidRenderer.Render(SequenceDefaultSourceFixture.Canonical(),new MermaidRenderOptions{WarningPolicy=MermaidWarningPolicy.Reject});Assert.Empty(result.Diagnostics);var document=Assert.IsType<MermaidSequenceDocument>(result.Document);Assert.Empty(document.Configuration.Settings);var model=Assert.IsType<SequenceArtifact>(result.Artifact!.Model);Assert.True(model.Layout!.MirrorParticipants);Assert.False(model.Layout.HideUnusedParticipants);Assert.Equal(150,model.Layout.ParticipantMinimumWidth);Assert.Equal(65,model.Layout.ParticipantMinimumHeight);Assert.Equal(50,model.Layout.ParticipantSpacing);Assert.Equal(TextAlignment.Center,model.Layout.MessageAlignment);Assert.Equal(TextAlignment.Center,model.Layout.NoteAlignment);Assert.Equal(SequenceSelfMessageRouting.Curved,model.Layout.SelfMessageRouting);Assert.Equal(1,model.Layout.FooterBottomMargin);Assert.Equal(.5,model.Paint.LifelineStroke!.Width);Assert.Empty(model.Paint.LifelineStroke.Dash!);Assert.Equal(14,model.Typography!.Participant!.FontSize);Assert.Equal(16,model.Typography.Message!.FontSize);Assert.Equal(14,model.Typography.Note!.FontSize);Assert.Equal(16,model.Typography.Fragment!.FontSize);Assert.Null(document.Configuration.SequenceForceMenus);
        var options=new MermaidSequenceRenderOptions{Padding=32,Presentation=new MermaidPresentationOptions{FontFamily="Courier New, monospace",FontSize=18}};var host=document.ToSequenceArtifact(options);Assert.Equal(ChartPadding.All(32),host.Layout!.CanvasPadding);Assert.All(new[]{host.Typography!.Participant,host.Typography.Message,host.Typography.Note,host.Typography.Fragment},s=>{Assert.Equal(18,s!.FontSize);Assert.Equal("Courier New, monospace",s.FontFamily);});SequenceMessageFixture.Capture("sequence-default-source-host",host);
        var fence=new MermaidVisualMarkupParser(new MermaidRenderOptions{WarningPolicy=MermaidWarningPolicy.Reject}).Parse("```mermaid\n"+SequenceDefaultSourceFixture.Canonical()+"\n```");Assert.Empty(fence.Diagnostics);Assert.Equal(result.Artifact.ToSvg(),Assert.Single(fence.Artifacts).ToSvg());Assert.Equal(result.Artifact.ToSvg(),document.ToSequenceArtifact().ToSvg());
    }
    [Fact] public void SourceExplicitFalseAndRoleBasePrecedenceRemainLiteral() {
        var source="%%{init:{\"fontFamily\":\"Georgia, serif\",\"sequence\":{\"mirrorActors\":false,\"wrap\":true,\"rightAngles\":true,\"actorFontSize\":20,\"labelBoxWidth\":0,\"labelBoxHeight\":0}}}%%\n"+SequenceDefaultSourceFixture.Canonical();var result=MermaidRenderer.Render(source,new MermaidRenderOptions{WarningPolicy=MermaidWarningPolicy.Reject});Assert.Empty(result.Diagnostics);var model=Assert.IsType<SequenceArtifact>(result.Artifact!.Model);Assert.False(model.Layout!.MirrorParticipants);Assert.True(model.Layout.WrapLabels);Assert.Equal(SequenceSelfMessageRouting.Orthogonal,model.Layout.SelfMessageRouting);Assert.Equal(50,model.Layout.FragmentTabMinimumWidth);Assert.Equal(15,model.Layout.FragmentTabMinimumHeight);Assert.Equal(20,model.Typography!.Participant!.FontSize);Assert.Equal("Georgia, serif",model.Typography.Message!.FontFamily);Assert.Equal(16,model.Typography.Message.FontSize);var prepared=SequencePreparedCompiler.PrepareDefault(model);SequenceMessageFixture.Capture("sequence-default-source-explicit",prepared);Assert.DoesNotContain(prepared.Regions,r=>r.Role=="sequence-participant-footer");Assert.All(Lines(prepared),line=>Assert.Equal("none",line.Attribute("stroke-dasharray")!.Value));
    }
    [Theory] [InlineData("bottomMarginAdj",-1)] [InlineData("labelBoxWidth",-1)] [InlineData("labelBoxHeight",-1)]
    public void UnsupportedNegativeSourceAllocationsRemainPreciselyLocated(string name,double value) {var result=MermaidRenderer.Render("%%{init:{\"sequence\":{\""+name+"\":"+value.ToString(CultureInfo.InvariantCulture)+"}}}%%\n"+SequenceDefaultSourceFixture.Canonical());SequenceSourcePolicyFixture.CaptureDiagnostics("sequence-default-invalid-"+name,result);Assert.True(result.HasErrors);Assert.Null(result.Artifact);Assert.Contains(result.Diagnostics,d=>d.Span.Line==1&&d.Message.Contains(name,StringComparison.Ordinal));}
    [Fact] public void NativeInvalidAllocationsAndInsufficientCompleteTabSpansRejectBeforePaint() {
        Assert.Throws<ArgumentOutOfRangeException>(()=>new SequenceLayoutPolicy(footerBottomMargin:-1));Assert.Throws<ArgumentOutOfRangeException>(()=>new SequenceLayoutPolicy(fragmentTabMinimumWidth:0));Assert.Throws<ArgumentOutOfRangeException>(()=>new SequenceLayoutPolicy(fragmentTabMinimumHeight:double.NaN));var model=Native();model.AddBlock(SequenceArtifactBlockKind.Loop,"Complete title",0,0);model.Layout=new SequenceLayoutPolicy(fragmentTabMinimumWidth:5000);Assert.Throws<NotSupportedException>(()=>model.Prepare(SequenceMessageFixture.Context()));
    }
    [Theory] [InlineData("compact",VisualThemeMode.Light)] [InlineData("compact",VisualThemeMode.Dark)] [InlineData("wide",VisualThemeMode.Light)] [InlineData("wide",VisualThemeMode.Dark)]
    public void CompleteNativeAndSourceRecipesStayInTheirRealPackageOwners(string variant,VisualThemeMode mode) {var model=SequenceSourceDefaultsRecipe.Create(variant,mode);SequenceMessageFixture.Capture("sequence-default-recipe-"+variant+"-"+mode,model);var native=ExampleRecipeSource.Emit(ExampleRecipes.Named("sequence-source-defaults"),variant,"Sequence allocation","Native policy",mode,variant=="compact"?390:1000,820,false,"Sequence");var source=ExampleRecipeSource.EmitSequenceSourceDefaults(variant,mode);Assert.DoesNotContain("ChartForgeX.Mermaid",native);Assert.Contains("fragmentTabMinimumWidth:",native);Assert.Contains("MermaidRenderer.Render",source);Assert.DoesNotContain("{{",source);}
    [Fact] public void EmptyAndRefilledViewsRetainRawIdsAndEarlierDetachedTabStrokeFacts() {var model=SequenceArtifact.Create("empty-default").WithSize(1500,1100).AddParticipant("A","Review").AddParticipant("B","Archive");model.Layout=new SequenceLayoutPolicy(mirrorParticipants:true,hideUnusedParticipants:true,fragmentTabMinimumWidth:100,fragmentTabMinimumHeight:40);model.Paint.LifelineStroke=new ChartStrokeStyle(width:.5,dash:Array.Empty<double>());var empty=model.Prepare(SequenceMessageFixture.Context());SequenceMessageFixture.Capture("sequence-default-empty",empty);var original=empty.ToSvg();Assert.Equal(2,empty.ToArtifact(model.Id,VisualArtifactKind.Sequence).ToInterchangeEnvelope().Nodes.Count);Assert.DoesNotContain(empty.Regions,r=>r.Role=="sequence-participant");model.AddMessage("A","B","Save");model.AddBlock(SequenceArtifactBlockKind.Loop,"Review",0,0);var refill=model.Prepare(SequenceMessageFixture.Context());SequenceMessageFixture.Capture("sequence-default-refill",refill);Assert.Equal(new[]{"A","B"},refill.Regions.Where(r=>r.Role=="sequence-lifeline").Select(r=>r.Id));Assert.Single(refill.Regions,r=>r.Role=="sequence-fragment-tab");Assert.Equal(original,empty.ToSvg());var svg=refill.ToSvg();model.Layout=new SequenceLayoutPolicy();model.Paint.LifelineStroke=null;model.Participants[0].Label="Changed";Assert.Equal(svg,refill.ToSvg());}
    private static SequenceArtifact Native()=>SequenceArtifact.Create("sequence-default").WithSize(1100,200).AddParticipant("A","Review").AddParticipant("B","Archive").AddMessage("A","B","Save");
    private static XElement[] Lines(PreparedVisual prepared)=>XDocument.Parse(prepared.ToSvg()).Descendants().Where(e=>(string?)e.Attribute("data-cfx-role")=="sequence-lifeline").ToArray();
}
internal static class SequenceDefaultSourceFixture {internal static string Canonical()=>File.ReadAllText(Path.Combine(TestRepository.Root,"Build","PackageConsumers","Adapters","sequence-source-defaults.mmd"));}
